// Report account balances from a ledger file.

const encoder = new TextEncoder();

// Amounts are whole units and two fraction digits; cents are kept as BigInt so sums stay exact.
function to_cents(amount: string): bigint {
  const [whole, fraction] = amount.split(".");
  return BigInt(whole) * 100n + BigInt(fraction);
}

function format_cents(cents: bigint): string {
  const sign = cents < 0n ? "-" : "";
  const abs = cents < 0n ? -cents : cents;
  const fraction = String(abs % 100n).padStart(2, "0");
  return `${sign}${abs / 100n}.${fraction}`;
}

// Compare by UTF-8 bytes, as the contract requires; JS string order is by UTF-16 units.
function compare_bytes(left: string, right: string): number {
  const a = encoder.encode(left);
  const b = encoder.encode(right);
  const shared = Math.min(a.length, b.length);
  for (let i = 0; i < shared; i++) {
    if (a[i] != b[i]) {
      return a[i] - b[i];
    }
  }
  return a.length - b.length;
}

function by_balance(left: [string, bigint], right: [string, bigint]): number {
  if (left[1] != right[1]) {
    return left[1] > right[1] ? -1 : 1;
  }
  return compare_bytes(left[0], right[0]);
}

function read_ledger(path: string): string[] {
  return Deno.readTextFileSync(path)
    .split(/\r?\n/)
    .filter((line) => line.trim() != "");
}

function parse_transaction(line: string): { account: string; kind: string; amount: string } {
  const [, account, kind, amount] = line.trim().match(/^(.*)\s+(\S+)\s+(\S+)$/) ?? [];
  return { account, kind, amount };
}

function main() {
  const lines = read_ledger(Deno.args[0]);
  const n = Number(lines[0].trim().split(/\s+/)[1]);

  const transactions = lines.slice(1, 1 + n).map(parse_transaction);
  const bad = transactions.findIndex((t) => t.kind != "debit" && t.kind != "credit");
  if (bad >= 0) {
    console.log(`ERROR line ${bad + 1}`);
    return;
  }

  // A balance is credits minus debits.
  const balances = new Map<string, bigint>();
  for (const { account, kind, amount } of transactions) {
    const cents = to_cents(amount);
    const signed = kind == "credit" ? cents : -cents;
    balances.set(account, (balances.get(account) ?? 0n) + signed);
  }

  const entries = [...balances.entries()].sort(by_balance);
  let total = 0n;
  for (const [account, balance] of entries) {
    console.log(`${account} ${format_cents(balance)}`);
    total = total + balance;
  }
  console.log(`TOTAL ${format_cents(total)}`);
}

main();

